// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** An operation under surgical site infection surveillance (MSDS COP 50). */
export interface SurveillanceOut {
  booking_id: number;
  booking_number: string;
  procedure_name: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  ot_id: number | null;
  ot_name: string | null;
  primary_surgeon_id: number;
  surgeon_name: string;
  wound_class: "Clean" | "CleanContaminated" | "Contaminated" | "Dirty" | null;
  implant_left: boolean;
  operated_on: string;
  /** ssi_followup_days, or ssi_implant_followup_days with an implant */
  window_days: number;
  /** Days since the operation */
  day: number;
  last_check: string | null;
  checks: number;
  /** A check in the last week of the window or later */
  closing_check: boolean;
  /** A surgical site infection reported for it */
  infection: "Suspected" | "Confirmed" | "Excluded" | null;
  state: "InWindow" | "Due" | "Overdue" | "Complete";
}

export interface SsiCheckIn {
  /** Default: today */
  checked_on?: string | null;
  method: "Ward" | "OPD" | "Telephone" | "HomeVisit";
  wound: "Healed" | "Healing" | "SignsOfInfection" | "NotAssessed";
  note?: string | null;
  /** Signs of infection: the suspected depth (a case is opened) */
  ssi_depth?: "Superficial" | "Deep" | "OrganSpace" | null;
}

export interface SurveillanceDetailOut {
  booking_id: number;
  booking_number: string;
  procedure_name: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  ot_id: number | null;
  ot_name: string | null;
  primary_surgeon_id: number;
  surgeon_name: string;
  wound_class: "Clean" | "CleanContaminated" | "Contaminated" | "Dirty" | null;
  implant_left: boolean;
  operated_on: string;
  /** ssi_followup_days, or ssi_implant_followup_days with an implant */
  window_days: number;
  /** Days since the operation */
  day: number;
  last_check: string | null;
  checks: number;
  /** A check in the last week of the window or later */
  closing_check: boolean;
  /** A surgical site infection reported for it */
  infection: "Suspected" | "Confirmed" | "Excluded" | null;
  state: "InWindow" | "Due" | "Overdue" | "Complete";
  check_list: SsiCheckOut[];
}

export interface SsiCheckOut {
  check_id: number;
  checked_on: string;
  method: "Ward" | "OPD" | "Telephone" | "HomeVisit";
  wound: "Healed" | "Healing" | "SignsOfInfection" | "NotAssessed";
  note: string | null;
  case_id: number | null;
  checked_by_name: string;
  checked_at: string;
}

export interface SsiRatesOut {
  date_from: string;
  date_to: string;
  /** Operations that ended in the period: the denominator */
  operations: number;
  infections: number;
  rate_pct: number | null;
  surveillance_complete: number;
  surveillance_complete_pct: number | null;
  by_surgeon: RateGroupOut[];
  by_procedure: RateGroupOut[];
  by_theatre: RateGroupOut[];
  by_wound_class: RateGroupOut[];
  by_month: RateGroupOut[];
  /** Confirmed cases of every kind, by their onset in the period */
  healthcare_infections: InfectionCountOut[];
  suspected_now: number;
}

export interface RateGroupOut {
  key: string;
  label: string | null;
  operations: number;
  /** Confirmed surgical site infections */
  infections: number;
  surveillance_complete: number;
  rate_pct: number | null;
}

export interface InfectionCountOut {
  key: string;
  count: number;
}

/** Operations under wound surveillance — GET /api/v1/infection/ssi-surveillance (who may call: holders of infection.control.manage or infection.statistics.view). */
export function ssiSurveillance(query?: { state?: string | null; surgeon_id?: number | null; limit?: number }): Promise<SurveillanceOut[]> {
  return api<SurveillanceOut[]>("GET", withQuery(`/infection/ssi-surveillance`, query), undefined);
}

/** Record a wound check after an operation — POST /api/v1/ot/bookings/{booking_id}/ssi-checks (who may call: holders of infection.case.report or infection.control.manage). */
export function recordCheckOtBookingsSsiChecks(booking_id: number, body: SsiCheckIn): Promise<SurveillanceDetailOut> {
  return api<SurveillanceDetailOut>("POST", `/ot/bookings/${booking_id}/ssi-checks`, body, { idempotent: true });
}

/** Surgical site infection rates — GET /api/v1/infection/ssi-rates (who may call: holders of infection.statistics.view or infection.control.manage). */
export function ssiRates(query?: { date_from?: string | null; date_to?: string | null }): Promise<SsiRatesOut> {
  return api<SsiRatesOut>("GET", withQuery(`/infection/ssi-rates`, query), undefined);
}
